@dataclass(frozen=True)
class Request:
    url: str
    headers: dict[str, str]
    timeout: float

class RequestBuilder:
    def __init__(self, url: str):
        self.url, self.headers, self.timeout = url, {}, 10.0
    def header(self, key: str, value: str) -> Self:
        self.headers[key] = value; return self
    def with_timeout(self, seconds: float) -> Self:
        if seconds <= 0: raise ValueError("timeout must be positive")
        self.timeout = seconds; return self
    def build(self) -> Request:
        return Request(self.url, dict(self.headers), self.timeout)

