from functools import wraps

def timed(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        start = monotonic()
        try: return fn(*args, **kwargs)
        finally: metrics.timing(fn.__name__, monotonic() - start)
    return wrapper

