class CheckoutFacade:
    def __init__(self, inventory, payments, orders, events):
        self.inventory = inventory; self.payments = payments
        self.orders = orders; self.events = events

    def place_order(self, cart: Cart, token: str) -> OrderId:
        reservation = self.inventory.reserve(cart.items)
        try:
            charge = self.payments.charge(cart.total, token)
            order = self.orders.create(cart, reservation, charge)
            self.events.publish(OrderPlaced(order.id))
            return order.id
        except Exception:
            self.inventory.release(reservation)
            raise

