from collections.abc import Callable

class EventBus:
    def __init__(self): self._handlers: dict[type, list[Callable]] = {}
    def subscribe(self, event_type: type, handler: Callable) -> Callable[[], None]:
        handlers = self._handlers.setdefault(event_type, [])
        handlers.append(handler)
        return lambda: handlers.remove(handler)
    def publish(self, event: object) -> None:
        for handler in tuple(self._handlers.get(type(event), ())):
            handler(event)

class OrderState(Protocol):
    def pay(self, order: "Order") -> None: ...
    def ship(self, order: "Order") -> None: ...

class Pending:
    def pay(self, order): order.state = Paid()
    def ship(self, order): raise InvalidTransition("pay before shipping")

class Paid:
    def pay(self, order): raise InvalidTransition("already paid")
    def ship(self, order): order.state = Shipped()

@dataclass
class Order:
    state: OrderState = field(default_factory=Pending)

