from abc import ABC, abstractmethod

class Importer(ABC):
    def import_file(self, path: Path) -> int:
        raw = path.read_bytes()
        rows = self.parse(raw)
        valid = [row for row in rows if self.validate(row)]
        self.persist(valid)
        return len(valid)
    @abstractmethod
    def parse(self, raw: bytes) -> list[dict]: ...
    def validate(self, row: dict) -> bool: return True
    @abstractmethod
    def persist(self, rows: list[dict]) -> None: ...

