class Visitor(Protocol):
    def visit_number(self, node: "Number"): ...
    def visit_add(self, node: "Add"): ...

@dataclass(frozen=True)
class Number:
    value: int
    def accept(self, visitor: Visitor): return visitor.visit_number(self)

@dataclass(frozen=True)
class Add:
    left: "Expr"; right: "Expr"
    def accept(self, visitor: Visitor): return visitor.visit_add(self)

from functools import singledispatch

@singledispatch
def evaluate(node): raise TypeError(type(node))

@evaluate.register
def _(node: Number): return node.value

@evaluate.register
def _(node: Add): return evaluate(node.left) + evaluate(node.right)
